import { loadFont } from "@remotion/google-fonts/Inter";
import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The bands sliding in from alternating sides, the gaps closing when the word
// settles solid, and the bands passing on through after the hold. Frames on
// the 30 fps scene timeline, after `speed`. The ids are public: a saved
// `timing` prop refers to them.

type StripeTypeElementId = `band:${number}` | "close" | `exit:${number}`;

interface StripeTypeTimingProps {
  stripes?: number;
  settle?: "striped" | "solid";
  exit?: boolean;
  hold?: number;
}

const DEFAULT_STRIPES = 8;
const DEFAULT_HOLD = 30;

/** Beats on the 30 fps clock. */
const STRIPE_TIMING = {
  stagger: 2,
  travel: 16,
  close: 10,
  /** Frames of empty screen after the exit in the preview. */
  tail: 10,
} as const;

function finite(value: number | undefined, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

/** The number of bands: a whole number, at least one. */
function stripeCount(stripes: number | undefined) {
  return Math.max(1, Math.round(finite(stripes, DEFAULT_STRIPES)));
}

/** When the bands have locked, the gaps have closed and the exit runs. */
function stripePhases(options: StripeTypeTimingProps = {}) {
  const n = stripeCount(options.stripes);
  const { stagger, travel, close, tail } = STRIPE_TIMING;
  const entered = stagger * (n - 1) + travel;
  const settled = options.settle === "solid" ? entered + close : entered;
  const hold = Math.max(0, finite(options.hold, DEFAULT_HOLD));
  const exitStart = settled + hold;
  const exitEnd = exitStart + stagger * (n - 1) + travel;
  const exit = options.exit !== false;
  return {
    entered,
    settled,
    exitStart,
    exitEnd,
    duration: exit ? exitEnd + tail : settled + hold,
  };
}

// Each band slides in over its own element, `stagger` after the one before
// it. `close` follows the last band when the word settles solid. On the exit
// each band leaves over `exit:<k>`, the first one after the hold.
const stripeTypeTimeline = defineTimeline<
  StripeTypeElementId,
  StripeTypeTimingProps
>((options) => {
  const n = stripeCount(options.stripes);
  const { stagger, travel, close } = STRIPE_TIMING;
  const { entered, exitStart } = stripePhases(options);
  const elements: TimelineElement<StripeTypeElementId>[] = [];
  for (let k = 0; k < n; k++) {
    elements.push({
      id: `band:${k}`,
      lane: "Bands in",
      label: `band ${k + 1}`,
      start: stagger * k,
      length: travel,
      follows: k > 0 ? `band:${k - 1}` : undefined,
    });
  }
  let last: StripeTypeElementId = `band:${n - 1}`;
  if (options.settle === "solid") {
    elements.push({
      id: "close",
      lane: "Gaps",
      label: "close",
      start: entered,
      length: close,
      follows: last,
    });
    last = "close";
  }
  if (options.exit !== false) {
    for (let k = 0; k < n; k++) {
      elements.push({
        id: `exit:${k}`,
        lane: "Bands out",
        label: `band ${k + 1}`,
        start: exitStart + stagger * k,
        length: travel,
        follows: k > 0 ? `exit:${k - 1}` : last,
      });
    }
  }
  return elements;
});

const { fontFamily: INTER } = loadFont("normal", {
  weights: ["100", "900"],
  subsets: ["latin"],
});

type StripeTypeSettle = "striped" | "solid";

interface StripeTypeProps {
  text?: string;
  fontSize?: number;
  fontWeight?: number;
  fontFamily?: string;
  color?: string;
  stripes?: number;
  gap?: number;
  settle?: StripeTypeSettle;
  exit?: boolean;
  hold?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches single bands, the closing of the gaps and the
   * exit, by the ids in `./timeline`. Frames on the scene timeline, after
   * `speed`.
   */
  timing?: Timing<StripeTypeElementId>;
}

const stripeTypeDefaults = {
  text: "Launch",
  fontSize: 180,
  fontWeight: 800,
  fontFamily: INTER,
  color: "#fafafa",
  stripes: DEFAULT_STRIPES,
  gap: 0.35,
  settle: "striped",
  exit: true,
  hold: DEFAULT_HOLD,
  speed: 1,
} satisfies Required<Omit<StripeTypeProps, "className" | "timing">>;

/** Beats on the 30 fps clock. */
const stripeTypeTiming = STRIPE_TIMING;

/** Ink box of Inter in a `line-height: 1` box, in em from the top, until measured. */
const INTER_INK = { top: 0.136, bottom: 0.864 + 0.24 };
const MEASURE_SIZE = 100;

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Expo-shaped curves that land exactly on 0 and 1 (Easing.exp stops 2⁻¹⁰ short).
const easeOutExpo = Easing.bezier(0.16, 1, 0.3, 1);
const easeInExpo = Easing.bezier(0.7, 0, 0.84, 0);
const easeInOutCubic = Easing.inOut(Easing.cubic);

/** Maps a composition frame onto the 30 fps timeline, scaled by `speed`. */
function getStripeTypeTime(
  frame: number,
  options: { fps?: number; speed?: number } = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const speed = Math.max(0, finite(options.speed, 1));
  return (Math.max(0, finite(frame, 0)) * 30 * speed) / fps;
}

interface StripeBand {
  /** Top of the band as a share of the ink box height. */
  top: number;
  /** Bottom of the band as a share of the ink box height. */
  bottom: number;
}

/**
 * Bands over the ink box. With `n` bands and gap share `g` the pitch is
 * `1 / (n − g)`: the first band starts at the top, the last ends at the
 * bottom.
 */
function getStripeBands(stripes: number, gap: number): StripeBand[] {
  const n = stripeCount(stripes);
  const g = Math.min(0.95, Math.max(0, finite(gap, 0)));
  const pitch = 1 / (n - g);
  return Array.from({ length: n }, (_, k) => ({
    top: k * pitch,
    bottom: k * pitch + pitch * (1 - g),
  }));
}

interface StripeTypeTimeline {
  /** Frame where the last band has locked. */
  entered: number;
  /** Frame where the gaps have closed (equals `entered` when striped). */
  settled: number;
  exitStart: number;
  exitEnd: number;
  /** Frames the preview needs. */
  duration: number;
}

function getStripeTypeTimeline(
  options: Pick<StripeTypeProps, "stripes" | "settle" | "exit" | "hold"> = {},
): StripeTypeTimeline {
  return stripePhases(options);
}

type StripeOptions = Pick<
  StripeTypeProps,
  "stripes" | "settle" | "exit" | "hold"
>;

/** The default schedule for `options`, when no resolved one is passed. */
const scheduleOf = (options: StripeOptions) =>
  resolve(stripeTypeTimeline(options, { length: 0 }));

/** Preview length for the given options and speed. */
function getStripeTypeDuration(
  options: Pick<
    StripeTypeProps,
    "stripes" | "settle" | "exit" | "hold" | "speed"
  > = {},
) {
  const speed = finite(options.speed, 1);
  if (speed <= 0) return 1;
  return Math.ceil(getStripeTypeTimeline(options).duration / speed);
}

/**
 * Horizontal offset of band `k` as a share of its travel distance: −1 or 1
 * off the frame, 0 locked. Even bands enter from the left, odd from the right,
 * and on the exit each band passes on through the other side.
 */
function getStripeBandOffset(
  t: number,
  k: number,
  options: StripeOptions = {},
  schedule: ResolvedTimeline<StripeTypeElementId> = scheduleOf(options),
) {
  const side = k % 2 === 0 ? -1 : 1;
  const bandIn = schedule.get(`band:${k}`);
  const enter = interpolate(t, [bandIn.start, bandIn.end], [1, 0], {
    ...CLAMP,
    easing: easeOutExpo,
  });
  // `|| 0` folds −0 into 0 for a locked band.
  if (options.exit === false) return side * enter || 0;
  const bandOut = schedule.get(`exit:${k}`);
  const leave = interpolate(t, [bandOut.start, bandOut.end], [0, 1], {
    ...CLAMP,
    easing: easeInExpo,
  });
  return side * enter - side * leave || 0;
}

/** Gap share over time: the set gap, closing to 0 when `settle` is solid. */
function getStripeGap(
  t: number,
  gap: number,
  options: Pick<StripeTypeProps, "stripes" | "settle"> = {},
  schedule: ResolvedTimeline<StripeTypeElementId> = scheduleOf(options),
) {
  if (options.settle !== "solid") return gap;
  const closing = schedule.get("close");
  return interpolate(t, [closing.start, closing.end], [gap, 0], {
    ...CLAMP,
    easing: easeInOutCubic,
  });
}

/** Ink box of the word in its `line-height: 1` box, and its width, in em. */
function useInkBox(text: string, font: string) {
  const [ink, setInk] = useState<{
    top: number;
    bottom: number;
    width: number;
  } | null>(null);

  useEffect(() => {
    const handle = delayRender("stripe-type: measuring the word");
    let released = false;
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    const measure = () => {
      if (released) return;
      const ctx = document.createElement("canvas").getContext("2d");
      if (ctx) {
        ctx.font = font;
        const m = ctx.measureText(text);
        const ascent = m.fontBoundingBoxAscent / MEASURE_SIZE;
        const descent = m.fontBoundingBoxDescent / MEASURE_SIZE;
        const baseline = (1 - (ascent + descent)) / 2 + ascent;
        if (ascent > 0) {
          setInk({
            top: baseline - m.actualBoundingBoxAscent / MEASURE_SIZE,
            bottom: baseline + m.actualBoundingBoxDescent / MEASURE_SIZE,
            width: m.width / MEASURE_SIZE,
          });
        }
      }
      release();
    };
    document.fonts.load(font, text).then(measure, measure);
    return release;
  }, [text, font]);

  return ink;
}

function StripeTypeBase(props: StripeTypeProps) {
  const {
    text = stripeTypeDefaults.text,
    fontSize = stripeTypeDefaults.fontSize,
    fontWeight = stripeTypeDefaults.fontWeight,
    fontFamily = stripeTypeDefaults.fontFamily,
    color = stripeTypeDefaults.color,
    stripes = stripeTypeDefaults.stripes,
    gap = stripeTypeDefaults.gap,
    settle = stripeTypeDefaults.settle,
    exit = stripeTypeDefaults.exit,
    hold = stripeTypeDefaults.hold,
    speed = stripeTypeDefaults.speed,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { fps, width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    stripeTypeTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const unit = height / 720;
  const size = fontSize * unit;
  const t = getStripeTypeTime(frame, { fps, speed });
  const measured = useInkBox(
    text,
    `${fontWeight} ${MEASURE_SIZE}px ${fontFamily}`,
  );
  const ink = measured ?? {
    ...INTER_INK,
    width: 0.6 * Array.from(text).length,
  };
  const options = { stripes, settle, exit, hold };
  const bands = getStripeBands(stripes, getStripeGap(t, gap, options, tl));
  const inkHeight = ink.bottom - ink.top;
  // Far enough that a band starting on either side is fully off the frame.
  const travel = (width + ink.width * size) / 2 + 0.2 * size;

  const type = {
    fontFamily,
    fontSize: size,
    lineHeight: 1,
    fontWeight,
    fontVariationSettings: `"wght" ${fontWeight}`,
    color,
    whiteSpace: "pre",
  } as const;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <div style={{ position: "relative" }}>
        <div aria-hidden style={{ ...type, visibility: "hidden" }}>
          {text}
        </div>
        {bands.map((band, k) => {
          const top = (ink.top + band.top * inkHeight) * 100;
          // Each band reaches a pixel into the next gap, so closed gaps leave
          // no antialiased seam between bands.
          const bleed = k < bands.length - 1 ? Math.max(1, unit) / size : 0;
          const bottom =
            (1 - (ink.top + band.bottom * inkHeight) - bleed) * 100;
          const offset = getStripeBandOffset(t, k, options, tl);
          return (
            <div
              key={k}
              aria-hidden={k > 0}
              style={{
                ...type,
                position: "absolute",
                inset: 0,
                clipPath: `inset(${top}% -1% ${bottom}% -1%)`,
                transform: `translateX(${offset * travel}px)`,
              }}
            >
              {text}
            </div>
          );
        })}
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Launch",
    description: "Text",
  },
  color: {
    type: "color",
    default: "#fafafa",
    description: "Text color",
  },
  settle: {
    type: "enum",
    default: "striped",
    variants: {
      striped: {},
      solid: {},
    },
    description: "Settle",
  },
  fontSize: {
    type: "number",
    default: 180,
    min: 60,
    max: 320,
    step: 2,
    description: "Font size",
    hiddenFromList: false,
  },
  fontWeight: {
    type: "number",
    default: 800,
    min: 100,
    max: 900,
    step: 50,
    description: "Weight",
    hiddenFromList: false,
  },
  stripes: {
    type: "number",
    default: 8,
    min: 2,
    max: 16,
    step: 1,
    description: "Stripes",
    hiddenFromList: false,
  },
  gap: {
    type: "number",
    default: 0.35,
    min: 0,
    max: 0.8,
    step: 0.05,
    description: "Gap",
    hiddenFromList: false,
  },
  hold: {
    type: "number",
    default: 30,
    min: 0,
    max: 120,
    step: 5,
    description: "Hold",
    hiddenFromList: false,
  },
  exit: {
    type: "boolean",
    default: true,
    description: "Exit",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","color","settle","fontSize","fontWeight","stripes","gap","hold","exit","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Launch",
  color: "#fafafa",
  settle: "striped",
  fontSize: 180,
  fontWeight: 800,
  stripes: 8,
  gap: 0.35,
  hold: 30,
  exit: true,
  speed: 1,
};

type StripeTypeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof StripeTypeBase>;

const StripeTypeInner = forwardRef<
  HTMLDivElement,
  StripeTypeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<StripeType>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <StripeTypeBase
          {...(componentProps as unknown as ComponentProps<typeof StripeTypeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const StripeType = Interactive.withSchema({
  Component: StripeTypeInner,
  componentName: "<StripeType>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
